def inside(x, y, poly):
    c = False
    n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]; xj, yj = poly[j]
        if ((yi > y) != (yj > y)) and (x < (xj - xi) * (y - yi) / (yj - yi + 1e-12) + xi):
            c = not c
        j = i
    return c

step = float(sys.argv[1]) if len(sys.argv) > 1 else 1.8
dots = []
lat = 80
row = 0
while lat > -56:
    lon = -180 + (step / 2 if row % 2 else 0)
    while lon < 180:
        if any(inside(lon, lat, p) for p in P.values()) and not any(inside(lon, lat, h) for h in HOLES):
            x = (lon + 180) / 360 * 1000
            y = (90 - lat) / 180 * 500
            dots.append((round(x, 1), round(y, 1)))
        lon += step
    lat -= step * 0.866
    row += 1

out = 'web' if len(sys.argv) < 3 else sys.argv[2]
flat = [v for d in dots for v in d]
with open('/home/claude/nuhash-portfolio/lib/worldDots.ts', 'w') as f:
    f.write('/** Dot-matrix world map (generated by scripts/world-dots.py). x,y pairs in a 1000x500 equirectangular space. */\n')
    f.write(f'export const WORLD_STEP = {step};\n')
    f.write('export const WORLD_DOTS: number[] = ' + json.dumps(flat, separators=(',', ':')) + ';\n')
print(len(dots), 'dots')
# preview
svg = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 500" width="1600" height="800"><rect width="1000" height="500" fill="#0b0908"/>']
for x, y in dots:
    svg.append(f'<circle cx="{x}" cy="{y}" r="1.6" fill="#f6f4f0" opacity="0.55"/>')
svg.append('</svg>')
open('/tmp/claude-0/-home-claude/6fe87e9f-cade-5ed7-bcae-ccfd8ad74bd6/scratchpad/world.svg', 'w').write('\n'.join(svg))
